describe('Early stopping and observed trends', () => {
  it('returns aligned finite training and validation histories from a real fit', () => {
    expect(history).toBeDefined();
    expect(history instanceof tf.History).toBe(true);
    const loss = history.history.loss,
      val = history.history.val_loss;
    expect(loss.length).toBeGreaterThan(0);
    expect(loss.length).toBeLessThanOrEqual(500);
    expect(val.length).toBe(loss.length);
    expect([...loss, ...val].every((v) => Number.isFinite(v) && v >= 0)).toBe(true);
    expect(history.params.samples).toBe(80);
    const batch = history.params.batchSize || 32;
    expect(batch >= 8 && batch <= 64).toBe(true);
    expect(model.optimizer.iterations).toBe(Math.ceil(80 / batch) * loss.length);
  });
  it('attaches the validation callback to the fit that produced history', () => {
    const fit = tf.__fits.find((entry) => entry && entry.history === history);
    expect(fit, 'No recorded model.fit call produced this history. Await the training call.').toBeDefined();
    expect(fit.callbacks.some((c) => c.monitor === 'val_loss' && c.patience === 5 && c.minDelta === 0),
      'The requested early-stopping callback never reached this fit. Pass it in the callbacks option.').toBe(true);
  });
  it('stops on five consecutive non-improvements, watching validation rather than training', async () => {
    const probe = async (values) => {
      const callback = makeEarlyStopping(),
        m = tf.sequential();
      m.add(tf.layers.dense({ units: 1, inputShape: [1] }));
      m.compile({ optimizer: 'sgd', loss: 'meanSquaredError' });
      m.stopTraining = false;
      callback.setModel(m);
      await callback.onTrainBegin({});
      let seen = 0;
      for (let i = 0; i < values.length; i++) {
        await callback.onEpochEnd(i, { val_loss: values[i], loss: 10 - i });
        seen++;
        if (m.stopTraining) break;
      }
      const stopped = m.stopTraining;
      m.dispose();
      return { seen, stopped };
    };
    expect(await probe([1, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.4])).toEqual({ seen: 7, stopped: true });
    expect(await probe([1, 0.9, 0.8, 0.7, 0.6, 0.5, 0.4, 0.3])).toEqual({
      seen: 8,
      stopped: false,
    });
    expect(await probe([1, 0.999, 0.998, 0.997, 0.996, 0.995, 0.994, 0.993])).toEqual({
      seen: 8,
      stopped: false,
    });
    expect(await probe([1, 1, 1, 0.9, 0.9, 0.9, 0.9, 0.9, 0.9])).toEqual({
      seen: 9,
      stopped: true,
    });
  });
  it('respects patience when a real run ends before the budget', () => {
    const v = history.history.val_loss;
    if (v.length === 500) return;
    let best = 0;
    for (let i = 1; i < v.length; i++) if (v[i] < v[best]) best = i;
    expect(v.length - 1 - best).toBe(5);
  });
  it('distinguishes validation trends using both curves', () => {
    const curve = (a, b) => [...Array(10).fill(a), ...Array(10).fill(b)];
    for (const [tr, va, want] of [
      [[1, 0.8], [1, 0.8], 'validation-improving'],
      [[1, 0.8], [1, 1.2], 'train-down-validation-up'],
      [[1, 1.2], [1, 1.2], 'both-worsening'],
      [[1, 1], [1, 1.2], 'validation-worsening'],
      [[1, 0.8], [1, 1], 'plateau'],
      [[1, 1], [0, 0], 'plateau'],
      [[0, 1], [0, 1], 'both-worsening'],
      [[1, 1], [1, 1.05], 'plateau'],
      [[1, 1], [1, 0.95], 'plateau'],
    ])
      expect(diagnose(curve(...tr), curve(...va))).toBe(want);
  });
  it('uses recent windows and accepts short histories without inventing a diagnosis', () => {
    expect(diagnose([], [])).toBe('insufficient-history');
    expect(diagnose([1], [2])).toBe('insufficient-history');
    const tr = [...Array(30).fill(20), ...Array(10).fill(1), ...Array(10).fill(0.8)],
      va = [...Array(30).fill(20), ...Array(10).fill(1), ...Array(10).fill(1.2)];
    expect(diagnose(tr, va)).toBe('train-down-validation-up');
    expect(() => diagnose([1], [])).toThrow();
    expect(() => diagnose([NaN], [1])).toThrow();
    expect(() => diagnose([-1], [1])).toThrow();
  });
});

