describe('Train DEEP SCAN, Then Read the Gap', () => {
  it('trained for exactly 30 epochs', () => {
    expect(
      history,
      'history is still null, so nothing about the run can be read. model.fit returns a promise, so the record it resolves to has to be awaited before it is stored.',
    ).toBeDefined();
    expect(
      history.history,
      'The record carries a history object holding one entry per epoch for every metric the run tracked.',
    ).toBeDefined();
    expect(
      history.history.loss,
      'The loss trace holds one entry per epoch, so its length is the epoch count the instructions asked for.',
    ).toHaveLength(30);
  });
  it('records finite losses without imposing a training outcome', () => {
    expect(history).toBeDefined();
    expect(history.history.loss.every((v) => Number.isFinite(v) && v >= 0)).toBe(true);
  });
  it('the training call saw the 100 archive rows and none of the 43 held out', () => {
    // The lesson's whole point, and the one thing this grader used to leave
    // unchecked: a submission that trained on the archive AND the held-out
    // slice cleared all eight tests on 2026-09-08 (audit round 5). Training
    // on the slice makes the held-out accuracy easier, not harder, so no
    // accuracy check anywhere can catch it. These two counters can.
    expect(
      history,
      'history is still null, so there is nothing recording what the training call was given.',
    ).toBeDefined();
    expect(
      history.params,
      'The record keeps the settings the run used, including how many rows went into it.',
    ).toBeDefined();
    expect(
      history.params.samples,
      'This is the row count model.fit was given. More than the archive holds means the held-out slice went into training, and every number you report afterwards is then measured on rows the gradients already saw. Fewer means part of the archive was held back inside fit (a validationSplit, say), and this exercise scores its held-out slice itself.',
    ).toBe(100);
    expect(
      model.optimizer.iterations,
      'This is how many weight updates the optimizer applied to this model: one per batch, so 30 sweeps over 100 rows in batches of 16. Zero means fit never ran on this model at all.',
    ).toBe(210);
  });
  it('the fit used the supplied training values, not an equal-sized mixture with test rows', () => {
    const fit = tf.__fits.find((entry) => entry && entry.history === history);
    expect(fit, 'No recorded model.fit call produced this history. Train the supplied model.').toBeDefined();
    expect(fit.x && fit.x.complete, 'The training inputs could not be inspected. Use the supplied tensor.').toBe(true);
    expect(fit.y && fit.y.complete, 'The training labels could not be inspected. Use the supplied tensor.').toBe(true);
    expect(fit.x.shape).toEqual(trainX.shape);
    expect(fit.y.shape).toEqual(trainY.shape);
    const pairedRows = (xs, ys) => Array.from({ length: xs.shape[0] }, (_, i) =>
      JSON.stringify([xs.values.slice(i * xs.shape[1], (i + 1) * xs.shape[1]), ys.values[i]])).sort();
    const suppliedX = { shape: trainX.shape, values: Array.from(trainX.dataSync()) };
    const suppliedY = { values: Array.from(trainY.dataSync()) };
    expect(pairedRows(fit.x, fit.y),
      'Keep the supplied training rows and their paired labels. Reordering pairs is valid; substituting test rows is leakage.').toEqual(pairedRows(suppliedX, suppliedY));
  });
  it('evaluates the original held-out rows and labels', () => {

    // The slice is pinned first. Without the three late-confirmed rows
    // every run scored a round 1.0 on both sides, so a typed-in 1 passed as
    // "the number this run produced" (round 7, 2026-09-13). Measured over
    // 60 runs with them in: the run misses all three every time, held-out
    // accuracy lands at 0.9302 and the gap at 0.07. Pinning the slice
    // stops the round number being restored by trimming it.
    expect(
      testX.shape,
      'testX is not the 43-row slice the exercise ships: 20 calm, 20 flagged, then the three late-confirmed rows from the lesson. The held-out numbers only mean something on that slice.',
    ).toEqual([43, 3]);
    expect(testY.shape, 'testY has to carry one label per held-out row, 43 of them.').toEqual([
      43, 1,
    ]);
    const tail = testX.slice([40, 0], [3, 3]).arraySync();
    const want = [
      [0.3, 0.68, 0.34],
      [0.26, 0.75, 0.29],
      [0.33, 0.71, 0.36],
    ];
    tail.forEach((row, i) =>
      row.forEach((v, j) => {
        expect(
          v,
          'Row ' +
            (40 + i) +
            ' of testX is not the late-confirmed window the starter placed there. Keep the supplied rows regardless of whether this run classifies them correctly.',
        ).toBeCloseTo(want[i][j], 4);
      }),
    );
    expect(
      Array.from(testY.dataSync()).slice(40),
      'The three late-confirmed rows are flagged windows, so their labels are 1.',
    ).toEqual([1, 1, 1]);


    expect(
      evalResult,
      'evalResult is still null. model.evaluate returns its scores directly, with no await needed.',
    ).toBeDefined();
    expect(
      Array.isArray(evalResult),
      'With a metric compiled in, evaluate returns a list: the loss first, then each compiled metric in order.',
    ).toBe(true);
    expect(
      evalResult.length,
      'This model compiles one metric, so the list holds the loss and that metric.',
    ).toBe(2);
    const fresh = model.evaluate(testX, testY);
    expect(
      evalResult[0].dataSync()[0],
      'The loss you stored does not match what the model scores on the held-out slice now.',
    ).toBeCloseTo(fresh[0].dataSync()[0], 4);
    expect(
      evalResult[1].dataSync()[0],
      'The accuracy you stored does not match what the model scores on the held-out slice now, so evaluate ran on something else.',
    ).toBeCloseTo(fresh[1].dataSync()[0], 4);

});

  it('diagnose reports a large gap above the stated boundary', () => {
    expect(
      diagnose(0.95, 0.6),
      'The training score exceeds the held-out score by more than 0.15. Report the gap; its cause needs investigation.',
    ).toBe('large-gap');
    expect(
      diagnose(0.99, 0.83),
      'The gap decides this one, not how high the training number is.',
    ).toBe('large-gap');
    expect(diagnose(0.9, 0.74), 'This spread clears the cutoff the instructions name.').toBe(
      'large-gap',
    );
    expect(
      diagnose(0.9, 0.76),
      'The gap is below the stated cutoff, so this rule raises no gap warning. That does not establish generalization.',
    ).toBe('no-gap-warning');
    expect(
      diagnose(0.93, 0.91),
      'These scores trigger neither condition. Return no-gap-warning; this is not a release decision.',
    ).toBe('no-gap-warning');
  });
  it('diagnose reports low scores only after checking the gap', () => {
    expect(
      diagnose(0.55, 0.52),
      'Both scores are below 0.7 and the gap is small. Report low-scores without assigning a cause.',
    ).toBe('low-scores');
    expect(
      diagnose(0.69, 0.69),
      'Both numbers sit just under the cutoff the instructions name.',
    ).toBe('low-scores');
    expect(
      diagnose(0.7, 0.7),
      'Both scores equal 0.7. The low-scores rule uses a strict comparison, so equality does not trigger it.',
    ).toBe('no-gap-warning');
    expect(diagnose(0.71, 0.71), 'Both scores exceed the stated low-score cutoff.').toBe(
      'no-gap-warning',
    );
    expect(
      diagnose(0.71, 0.69),
      'Only one of the two is below the cutoff, and the rule needs both.',
    ).toBe('no-gap-warning');
    expect(
      diagnose(0.69, 0.71),
      'Only one of the two is below the cutoff in this pair too, with the order flipped.',
    ).toBe('no-gap-warning');
    expect(
      diagnose(0.68, 0.4),
      'Both scores are low, but the gap exceeds 0.15. Check the gap first and return large-gap.',
    ).toBe('large-gap');
  });
  it('trainAcc and testAcc are the two numbers THIS run produced', () => {
    expect(
      history,
      'history is still null, so there is no training accuracy to read.',
    ).toBeDefined();
    expect(
      history.history,
      'The record carries its per-epoch traces in a history object.',
    ).toBeDefined();
    const acc = history.history.acc;
    expect(
      acc,
      'No accuracy trace came back. TFJS files the accuracy metric under a short key, one entry per epoch.',
    ).toBeDefined();
    expect(acc, 'The accuracy trace holds one entry per epoch, like the loss trace.').toHaveLength(
      30,
    );
    expect(
      trainAcc,
      'trainAcc has to be the final training accuracy of this run, which is the last entry of that trace.',
    ).toBe(acc[acc.length - 1]);
    const fresh = model.evaluate(testX, testY);
    expect(
      testAcc,
      'testAcc has to be the held-out accuracy of this run. evaluate returns tensors, so the number comes out with dataSync or data.',
    ).toBeCloseTo(fresh[1].dataSync()[0], 4);
  });
  it('reports the rule applied to the actual measured scores', () => {
    expect(typeof trainAcc).toBe('number');
    expect(typeof testAcc).toBe('number');
    expect(verdict).toBe(diagnose(trainAcc, testAcc));
  });
});

